{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "PubSub Topic not encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic uses Google-managed encryption keys by default. For production environments handling sensitive data like insurance claims, using a Customer-Managed Encryption Key (CMEK) via KMS provides better control over key rotation and access."
    }
  ],
  "patched_code": "resource "google_pubsub_topic" "notification_queue" {
  name = "insurance-claims-processing-platform-pubsub-notifications"
  labels = {
    environment = "production"
    component   = "notifications"
  }

  # Note: In a real implementation, you must define or reference a valid KMS CryptoKey.
  # This block adds the structure for CMEK compliance as per CKV_GCP_83.
  # Replace 'projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key' 
  # with your actual KMS key resource address or string.
  kms_key_name = google_kms_crypto_key.pubsub_encryption_key.id
}

# Added supporting resource to satisfy the CMEK requirement structurally.
# If an existing KMS key is available, remove this block and update kms_key_name above.
resource "google_kms_key_ring" "pubsub_keyring" {
  name     = "pubsub-notification-keyring"
  location = "us-central1"
}

resource "google_kms_crypto_key" "pubsub_encryption_key" {
  name        = "pubsub-notification-key"
  key_ring    = google_kms_key_ring.pubsub_keyring.id
  purpose     = "ENCRYPT_DECRYPT"
}",
  "fix_summary": "Added `kms_key_name` attribute to the PubSub topic to enable Customer-Managed Encryption Keys (CMEK). Included necessary `google_kms_key_ring` and `google_kms_crypto_key` resources to provide a valid reference for the encryption key, ensuring compliance with CKV_GCP_83."
}
